import 'package:bloc/bloc.dart';import "../../../../../../Config/Routes/route_name.dart";import '../../../../../../Core/Resources/app_constants.dart';import '../../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../../Core/Storage/Local/local_storage_service.dart';import '../../../../../../main.dart';import '../../../../../Global/Authentication/data/entities/user_data_model.dart';import '../../data/models/product_preview_entities.dart';import '../../domain/repositories/home_repo_impl.dart';import 'home_state_model.dart';class HomeCubit extends Cubit<HomeStateModel> {  HomeCubit(this.homeRepoImpl)      : super(HomeStateModel(          userDataModel: UserDataModel(            id: 0,            name: "User",            email: "User@gmail.com",            emailVerifiedAt: false,            phone: "",            photo: "",            photoUrl: "",            role: "",            status: "active",            carpenterProfile: "",            createdAt: null,            updatedAt: null,          ),        ));  final HomeRepoImpl homeRepoImpl;  Future<void> toggleFavorite(ProductPreviewEntities model) async {    await ProductStorageService.toggleProduct(model);    await loadFavoriteProducts();  }  bool isProductIn(ProductPreviewEntities model)  {    return ProductStorageService.isProductInList(model.id);  }  Future<void> loadFavoriteProducts() async {    final favoriteProducts = ProductStorageService.getAllProducts();    emit(state.copyWith(favoriteProductDetails: favoriteProducts));  }  Future<void> init() async {    _setLoading(AppConstants.kLoadingProductsFeatured, true);    _setLoading(AppConstants.kLoadingProductsPopular, true);    final token = LocalStorageService.getValue(      LocalStorageKeys.token,      defaultValue: "",    );    if (token.isNotEmpty) {      await getUserData();    }    await _getProductIsFeatured();    await _getProductIsPopular();  }  Future<void> _getProductIsFeatured() async {    final response = await homeRepoImpl.getProductIsFeatured();    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productsFeatured: data));      },    );    _setLoading(AppConstants.kLoadingProductsFeatured, false);  }  Future<void> _getProductIsPopular() async {    final response = await homeRepoImpl.getProductIsPopular();    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productsPopular: data));      },    );    _setLoading(AppConstants.kLoadingProductsPopular, false);  }  Future<void> getProductByID(int id) async {    final response = await homeRepoImpl.getProductDetails(id);    response.fold(      (failure) {},      (data) {        emit(state.copyWith(productDetails: data));      },    );  }  Future<void> getUserData() async {    final response = await homeRepoImpl.getUserDataModel();    response.fold(      (failure) async {        await handleUnauthorizedAccess();      },      (data) {        emit(state.copyWith(userDataModel: data));      },    );  }  void _setLoading(String key, bool value) {    emit(state.copyWith(      isLoading: {        ...state.isLoading,        key: value,      },    ));  }  Future<void> handleUnauthorizedAccess() async {    await LocalStorageService.removeValue(LocalStorageKeys.token);    await kNavigationService.clearAndNavigateTo(AppRoutes.authentication);  }}